@startuml

class Museum {
  + name : string
  + locations : Location[]
}

abstract class Location {}

class ExhibitionRoom {}

class Exhibition {
  + startDate : date
  + endDate : date
  + coordinator : Employee
  + items : ExhibitionItem[]
}

class ExhibitionItem {
  + desiredItems : DesiredItem[]
  + requestedPieces : RequestedPiece[]
}

class DesiredItem {
  + description : string
  + quantity : int
}

class RequestedPiece {
  + collector : Collector
  + piece : Piece
}

abstract class Employee {}

class JuniorEmployee {
  + coach : SeniorEmployee
}

class SeniorEmployee {}

class Collector {
  + pieces : Piece[]
}

abstract class Item {}

class Painting {}
class Drawing {}
class Sculpture {}

Item "1" -- "0..*" ExhibitionItem

ExhibitionRoom "1" -- "0..*" Exhibition

Museum "1" -- "0..*" Location
Location "1" -- "0..*" ExhibitionRoom

Employee "1" -- "0..*" JuniorEmployee

@enduml

